# One-shot helper for the CMake migration. Parses AAASeed_by_Maa.vcxproj and emits one
# Src/<subsys>/sources.cmake per top-level subsystem under Src/, plus Src/sources_root.cmake
# for the few files at Src/ root (action.cpp, aaaseed.cpp).
#
# Each emitted file is a target_sources call attaching .cpp + .h to the AAASeed target.
#
# Files marked ExcludedFromBuild=true in EVERY configuration are skipped (dead in the vcxproj).
# Files with per-config exclusions are flagged as TODO with an inline comment, included
# unconditionally for now (Phase F will revisit if needed).

[CmdletBinding()]
param(
    [string]$Vcxproj = "$PSScriptRoot\..\AAASeed_by_Maa.vcxproj",
    [string]$SrcRoot = "$PSScriptRoot\..\Src"
)

$ErrorActionPreference = 'Stop'

# Load the project as XML. The vcxproj uses the MSBuild XML namespace.
[xml]$xml = Get-Content -Raw -LiteralPath $Vcxproj
$ns = New-Object System.Xml.XmlNamespaceManager $xml.NameTable
$ns.AddNamespace('m', 'http://schemas.microsoft.com/developer/msbuild/2003')

function Get-Items {
    param($xml, $ns, $tag, $rootDir)
    $nodes = $xml.SelectNodes("//m:$tag", $ns)
    $list = @()
    $missingCount = 0
    foreach ($n in $nodes) {
        $include = $n.GetAttribute('Include')
        if (-not $include) { continue }
        $exclusions = $n.SelectNodes("m:ExcludedFromBuild", $ns)
        $allExcluded = $false
        $hasMixedExclusion = $false
        if ($exclusions.Count -gt 0) {
            $trueCount = 0
            $falseCount = 0
            foreach ($e in $exclusions) {
                if ($e.InnerText -eq 'true') { $trueCount++ } else { $falseCount++ }
            }
            # 16 vcxproj configs (4 configs * v143/v145 * Win32/x64) -- if all 16 are excluded,
            # the file is dead in every configuration.
            if ($trueCount -ge 16 -and $falseCount -eq 0) { $allExcluded = $true }
            elseif ($trueCount -gt 0 -and $falseCount -gt 0) { $hasMixedExclusion = $true }
            elseif ($trueCount -gt 0) {
                # Some configs exclude, others have no exclusion (= included). Treat as mixed.
                $hasMixedExclusion = $true
            }
        }
        if ($allExcluded) { continue }

        # Skip stale entries that point at files no longer present on disk.
        # These accumulate from removed sources / abandoned third-party trees that nobody
        # cleaned up in the vcxproj. CMake is strict about file existence so we filter here.
        $abs = Join-Path $rootDir $include
        if (-not (Test-Path -LiteralPath $abs)) {
            $missingCount++
            continue
        }

        $list += [PSCustomObject]@{
            Path  = $include
            Mixed = $hasMixedExclusion
        }
    }
    # Wrap in a PSCustomObject to avoid PowerShell unwrapping the array on multi-return.
    return [PSCustomObject]@{ Items = $list; MissingCount = $missingCount }
}

$rootDir = Split-Path -Parent $Vcxproj
$clRes = Get-Items $xml $ns 'ClCompile' $rootDir
$ihRes = Get-Items $xml $ns 'ClInclude' $rootDir
$cl = $clRes.Items
$ih = $ihRes.Items

"Active ClCompile (existing on disk) : $($cl.Count)"
"Active ClInclude (existing on disk) : $($ih.Count)"
"Stale ClCompile (in vcxproj but missing) : $($clRes.MissingCount)"
"Stale ClInclude (in vcxproj but missing) : $($ihRes.MissingCount)"
"Mixed-exclusion ClCompile (review needed) : $(($cl | Where-Object Mixed).Count)"


# Group by subsystem (first folder under Src\).
function Group-BySubsystem {
    param([object[]]$items, [string]$srcRoot)
    $groups = @{}
    foreach ($it in $items) {
        $p = $it.Path
        if (-not ($p -like 'Src\*')) { continue }
        $parts = $p -split '\\'
        if ($parts.Length -lt 2) { continue }
        if ($parts.Length -eq 2) {
            # File at Src/ root
            $key = '_root'
        } else {
            $key = $parts[1]
        }
        if (-not $groups.ContainsKey($key)) { $groups[$key] = @() }
        $groups[$key] += $it
    }
    return $groups
}

$cppGroups = Group-BySubsystem $cl  $SrcRoot
$hGroups   = Group-BySubsystem $ih  $SrcRoot


# Emit one sources.cmake per subsystem.
$allKeys = ($cppGroups.Keys + $hGroups.Keys) | Sort-Object -Unique

foreach ($k in $allKeys) {
    $cpps = if ($cppGroups.ContainsKey($k)) { $cppGroups[$k] } else { @() }
    $hs   = if ($hGroups.ContainsKey($k))   { $hGroups[$k]   } else { @() }

    if ($k -eq '_root') {
        $out = Join-Path $SrcRoot 'sources_root.cmake'
    } else {
        $dir = Join-Path $SrcRoot $k
        if (-not (Test-Path $dir)) {
            Write-Warning "Subsystem dir not found, skipping: $dir"
            continue
        }
        $out = Join-Path $dir 'sources.cmake'
    }

    $sb = [System.Text.StringBuilder]::new()
    [void]$sb.AppendLine("# Generated by tools/extract_sources_from_vcxproj.ps1 (CMake migration, Phase C).")
    [void]$sb.AppendLine("# Edit by hand only after disabling regeneration -- this file is meant to be authoritative.")
    [void]$sb.AppendLine("")
    [void]$sb.AppendLine("target_sources(AAASeed PRIVATE")

    foreach ($it in ($cpps | Sort-Object Path)) {
        $rel = $it.Path -replace '\\', '/'
        if ($it.Mixed) {
            [void]$sb.AppendLine("    `${CMAKE_SOURCE_DIR}/$rel    # TODO Phase F : review per-config exclusions in vcxproj")
        } else {
            [void]$sb.AppendLine("    `${CMAKE_SOURCE_DIR}/$rel")
        }
    }
    foreach ($it in ($hs | Sort-Object Path)) {
        $rel = $it.Path -replace '\\', '/'
        if ($it.Mixed) {
            [void]$sb.AppendLine("    `${CMAKE_SOURCE_DIR}/$rel    # TODO Phase F : review per-config exclusions in vcxproj")
        } else {
            [void]$sb.AppendLine("    `${CMAKE_SOURCE_DIR}/$rel")
        }
    }

    [void]$sb.AppendLine(")")

    [System.IO.File]::WriteAllText($out, $sb.ToString(), (New-Object System.Text.UTF8Encoding $false))
    "  wrote $out  ($(($cpps.Count) + ($hs.Count)) files)"
}
